import React, { useState, useEffect, useRef } from 'react';
import { useParams, useNavigate } from 'react-router-dom';
import { MapContainer, TileLayer, Marker, useMapEvents } from 'react-leaflet';
import 'leaflet/dist/leaflet.css';
import './editarMascota.css'; // Importá el CSS


const LocationSelector = ({ lat, lng, setLat, setLng }) => {
  useMapEvents({
    click(e) {
      console.log('Selector - Lat:', lat, 'Lng:', lng);
      setLat(e.latlng.lat);
      setLng(e.latlng.lng);
    },
  });

  return lat && lng ? <Marker position={[lat, lng]} /> : null;
};

const EditarMascotaPage = () => {
  const { id } = useParams();
  const navigate = useNavigate();
  const [mascota, setMascota] = useState(null);
  const [lat, setLat] = useState(null);
  const [lng, setLng] = useState(null);
  const fileInputRef = useRef(null); // Referencia para el input de archivo

  useEffect(() => {
    const fetchMascota = async () => {
      const res = await fetch(`http://localhost:3000/api/pets/${id}`);
      const data = await res.json();
      setMascota(data);
      setLat(data.lat || data.location?.lat || null);
      setLng(data.lng || data.location?.lng || null);
    };
    fetchMascota();
  }, [id]);

  const handleChange = (e) => {
    setMascota({ ...mascota, [e.target.name]: e.target.value });
  };

  const handleFileClick = () => {
    fileInputRef.current.click(); // Disparar el input de archivo
  };

  const handleFileChange = (e) => {
    const file = e.target.files[0];
    if (file) {
      const imageUrl = URL.createObjectURL(file); // Crear una URL para la imagen
      setMascota({ ...mascota, imageurl: imageUrl, file }); // Guardar el archivo y la URL
    }
  };

  const handleSubmit = async (e) => {
    e.preventDefault();
    
    let uploadedImageUrl = mascota.imageurl; // URL por defecto

    // Si hay un archivo nuevo, subirlo
    if (mascota.file) {
      const formData = new FormData();
      formData.append('file', mascota.file); // Asegúrate de que el nombre sea 'file'

      const uploadRes = await fetch('http://localhost:3000/api/upload', {
        method: 'POST',
        body: formData,
      });

      if (uploadRes.ok) {
        const uploadData = await uploadRes.json();
        uploadedImageUrl = uploadData.url; // Asumimos que el backend devuelve la URL
      } else {
        console.error('Error al subir la imagen');
        return; // Podrías mostrar un mensaje al usuario aquí
      }
    }

    // Actualizar la mascota con la URL de la imagen
    const updateRes = await fetch(`http://localhost:3000/api/pets/${id}`, {
      method: 'PUT',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({ ...mascota, imageurl: uploadedImageUrl, lat, lng }), // Cambiado a imageurl
    });

    if (updateRes.ok) {
      navigate('/mascotas-reportadas'); // Volver a la lista después de guardar
    } else {
      console.error('Error al actualizar la mascota'); // Manejo de errores
    }
  };

  if (!mascota) return <p>Cargando...</p>;

  return (
    <div className="body-container-editar">
      <div className="editar-mascota-container">
        <h1>Editar reporte de mascota</h1>
        <form onSubmit={handleSubmit} className="form-editar">
          <label>Nombre</label>
          <input 
            name="name" 
            value={mascota.name} 
            onChange={handleChange} 
            required 
          />
          
          <label>Foto</label>
          <img src={mascota.imageurl} className="mascota-image" />
          <input 
            type="file" 
            ref={fileInputRef} 
            style={{ display: 'none' }} 
            onChange={handleFileChange} 
            accept="image/*"
          />
          <button type="button" className="btn-modificar-foto" onClick={handleFileClick}>
            Modificar foto
          </button>

          <label>Ubicación</label>
          <input 
            name="location" 
            value={mascota.descripcion} 
            onChange={handleChange} 
            required 
          />

          {/* Aquí agregamos el mapa */}
          {lat && lng && (
            <MapContainer
  center={[lat, lng]}
  zoom={13}
  style={{ height: '400px', width: '100%' }} // Aumentá la altura para probar
>
              <TileLayer url="https://{s}.tile.openstreetmap.org/{z}/{x}/{y}.png" />
              <LocationSelector lat={lat} lng={lng} setLat={setLat} setLng={setLng} />
            </MapContainer>
          )}

          <button type="submit" className="btn-guardar">Guardar</button>
          <button type="button" className="btn-reportar-encontrado">Reportar como encontrado</button>
          <button type="button" className="btn-eliminar">Eliminar reporte</button>
        </form>
      </div>
    </div>
  );
};

export default EditarMascotaPage;
